document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll("#random-carousel");e.forEach(function(e){const n=e.querySelectorAll("img");if(n.length===0)return;const t=Array.from(n).map(function(e){return{src:e.getAttribute("src"),srcset:e.getAttribute("srcset"),alt:e.getAttribute("alt")}});for(let e=t.length-1;e>0;e--){const n=Math.floor(Math.random()*(e+1)),s=t[e];t[e]=t[n],t[n]=s}n.forEach(function(e,n){t[n].src&&e.setAttribute("src",t[n].src),t[n].srcset&&e.setAttribute("srcset",t[n].srcset),t[n].alt&&e.setAttribute("alt",t[n].alt)})})})